def mount(_params, _session, socket) do
  {:ok, assign(socket, :messages, []), temporary_assigns: [messages: []]}
end

def handle_info({:new_message, msg}, socket) do
  {:noreply, assign(socket, :messages, [msg])}
end

def handle_async(:report_gen, {:ok, report}, socket) do
  {:noreply, socket |> assign(:report, report) |> put_flash(:info, "Report ready")}
end

def handle_async(:report_gen, {:exit, reason}, socket) do
  {:noreply, put_flash(socket, :error, "Generation failed: #{inspect(reason)}")}
end

def handle_info({:order_created, order}, socket) do
  {:noreply, stream_insert(socket, :orders, order, at: 0)}
end

consume_uploaded_entries(socket, :avatar, fn %{path: path}, _entry ->
  dest = Path.join("priv/static/uploads", Path.basename(path))
  File.cp!(path, dest)
  {:ok, "/uploads/" <> Path.basename(dest)}
end)
